import{H as e,at as t,it as n,vt as r}from"./chunks/framework.dmHZ7NHG.js";var i=JSON.parse(`{"title":"SCIENCE + METAPHYSICS — Trinity Pairs","description":"","frontmatter":{},"headers":[],"relativePath":"docs/science.md","filePath":"docs/science.md"}`),a={name:`docs/science.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="science-metaphysics-—-trinity-pairs" tabindex="-1">SCIENCE + METAPHYSICS — Trinity Pairs <a class="header-anchor" href="#science-metaphysics-—-trinity-pairs" aria-label="Permalink to “SCIENCE + METAPHYSICS — Trinity Pairs”">​</a></h1><p><strong>The Honest Framework:</strong> Each science domain in trinity structure.</p><ol><li><strong>SEALED</strong> — What uuidna proves (decidable arithmetic, recomputable by anyone)</li><li><strong>HONEST BOUNDARY</strong> — What it cannot prove (what court/philosophy must decide)</li><li><strong>METAPHYSICAL PAIR</strong> — The philosophical question (for human judgment)</li></ol><p>Every sealed theorem is a <strong>foundation</strong>, not an answer. The metaphysical question is what the sealed truth <em>means</em>.</p><hr><h2 id="the-domains" tabindex="-1">The Domains <a class="header-anchor" href="#the-domains" aria-label="Permalink to “The Domains”">​</a></h2><h3 id="physics-cosmology" tabindex="-1">Physics &amp; Cosmology <a class="header-anchor" href="#physics-cosmology" aria-label="Permalink to “Physics &amp; Cosmology”">​</a></h3><p><strong><a href="./science/thermodynamics">Thermodynamics</a></strong> — Energy &amp; Entropy</p><ul><li>Sealed: First law conserves energy. Second law forbids entropy reversal. Carnot efficiency is bounded.</li><li>Honest Boundary: Whether entropy applies to information; whether heat death is inevitable; why time has an arrow.</li><li>Metaphysical Question: <em>Does entropy imply the universe tends toward chaos and meaninglessness?</em></li></ul><p><strong><a href="./science/relativity">Relativity</a></strong> — Spacetime &amp; Causality</p><ul><li>Sealed: Nothing exceeds <em>c</em>. Causality is defined by light cones. Time dilates, length contracts. E = mc².</li><li>Honest Boundary: Whether time &quot;really&quot; passes; why <em>c</em> is the limit; what causation &quot;means&quot; beyond structure.</li><li>Metaphysical Question: <em>Does relativity eliminate free will by making all events determined by prior light cones?</em></li></ul><p><strong><a href="./science/astronomy">Astronomy</a></strong> — Coming</p><ul><li>Sealed: Kepler&#39;s law T² = a³. Precession cycles. Eclipses recur on Saros.</li><li>Honest Boundary: Origin of the universe; whether the cosmos is finite or infinite; purpose.</li><li>Metaphysical Question: <em>Are we in a special place/time, or is the Earth arbitrary?</em></li></ul><h3 id="biology-life" tabindex="-1">Biology &amp; Life <a class="header-anchor" href="#biology-life" aria-label="Permalink to “Biology &amp; Life”">​</a></h3><p><strong><a href="./science/life">Life</a></strong> — Mechanism &amp; Meaning</p><ul><li>Sealed: DNA base-pairing (XOR, self-inverse). Neurons fire by threshold. Molecules bond by electron count.</li><li>Honest Boundary: Whether mechanism is &quot;all there is&quot;; whether consciousness reduces to neurons; meaning.</li><li>Metaphysical Question: <em>Can life be completely mechanical AND completely meaningful?</em></li></ul><p><strong><a href="./science/neuro">Neuro</a></strong> — Coming</p><ul><li>Sealed: Action potential is −70→+40 mV. Firing is all-or-none. Hebbian: Δw = pre·post.</li><li>Honest Boundary: How neurons become thought; the &quot;hard problem&quot; of consciousness.</li><li>Metaphysical Question: <em>Does understanding the brain diminish the mind?</em></li></ul><p><strong><a href="./science/diving">Diving</a></strong> — Coming</p><ul><li>Sealed: Partial pressures sum by Dalton&#39;s law. Nitrogen is narcotic. Decompression uses Haldane ratios.</li><li>Honest Boundary: Safety margin calculation; risk tolerance; when to trust the table vs. experience.</li><li>Metaphysical Question: <em>How do you decide when depth is worth the danger?</em></li></ul><h3 id="chemistry" tabindex="-1">Chemistry <a class="header-anchor" href="#chemistry" aria-label="Permalink to “Chemistry”">​</a></h3><p><strong><a href="./science/chemistry">Chemistry</a></strong> — Coming</p><ul><li>Sealed: Balanced equations conserve atoms. Charge conservation. Oxidation states sum to charge.</li><li>Honest Boundary: Mechanism of catalysis; why some reactions are fast/slow; synthesis prediction.</li><li>Metaphysical Question: <em>Is chemistry just applied physics, or does it have its own logic?</em></li></ul><p><strong><a href="./science/electromagnetism">Electromagnetism</a></strong> — Coming</p><ul><li>Sealed: Coulomb: like repel, opposite attract. Ohm&#39;s law. Kirchhoff conserves current &amp; voltage. Faraday induces EMF.</li><li>Honest Boundary: Why charge exists; unification with other forces; quantum effects.</li><li>Metaphysical Question: <em>Are fields &quot;real&quot; or just math for predicting particle behavior?</em></li></ul><h3 id="earth-navigation" tabindex="-1">Earth &amp; Navigation <a class="header-anchor" href="#earth-navigation" aria-label="Permalink to “Earth &amp; Navigation”">​</a></h3><p><strong><a href="./science/navigation">Navigation</a></strong> — Coming</p><ul><li>Sealed: Compass rose is ℤ/8 (eight 45° headings). Reciprocal bearing is +4. Dead reckoning is vector sum.</li><li>Honest Boundary: Weather unpredictability; map vs. territory mismatch; when instruments fail.</li><li>Metaphysical Question: <em>Can you navigate if you cannot see? What does &quot;lost&quot; mean?</em></li></ul><p><strong><a href="./science/tides">Tides</a></strong> — Coming</p><ul><li>Sealed: Rule of twelfths (1,2,3,3,2,1 = 12). Semidiurnal period 12h25m. Spring vs neap is phase addition.</li><li>Honest Boundary: Why tides matter to sailors; harbor prediction under rare conditions; surprise storms.</li><li>Metaphysical Question: <em>How much can you trust a regular pattern when the Moon and Sun align unpredictably?</em></li></ul><hr><h2 id="the-pattern" tabindex="-1">The Pattern <a class="header-anchor" href="#the-pattern" aria-label="Permalink to “The Pattern”">​</a></h2><p>Each domain:</p><ol><li><strong>Sealed Theorems</strong> — Proof links to the exact Lean file, <code>by decide</code></li><li><strong>What It Cannot Prove</strong> — The honest boundary of mathematics</li><li><strong>The Research Question</strong> — Open, for you to explore</li></ol><p><strong>Why this matters:</strong> Understanding physics, biology, chemistry, cosmology is the best gift humans can give each other. Sealing the proofs guarantees you can verify them yourself. Marking the boundaries guarantees no one will pretend to prove what requires judgment. The metaphysical questions are what make science <em>matter</em>.</p><hr><h2 id="how-to-read-this" tabindex="-1">How to Read This <a class="header-anchor" href="#how-to-read-this" aria-label="Permalink to “How to Read This”">​</a></h2><ol><li><strong>Start with Sealed:</strong> Read the theorem title. Follow the Lean link. Recompute <code>by decide</code> if you wish (it&#39;s instant).</li><li><strong>Trace the Boundary:</strong> What assumption did the proof make? What did it exclude? Where does mechanism end?</li><li><strong>Sit with the Question:</strong> The metaphysical question has no answer in mathematics. That&#39;s the point. Live with it. Let it shape how you understand the world.</li></ol><hr><h2 id="the-honest-scope" tabindex="-1">The Honest Scope <a class="header-anchor" href="#the-honest-scope" aria-label="Permalink to “The Honest Scope”">​</a></h2><p><strong>What this framework proves:</strong> Mathematics is consistent and recomputable. Sealed theorems are true. Boundaries are real.</p><p><strong>What this framework cannot prove:</strong></p><ul><li>Whether the universe is deterministic or has free will</li><li>Whether life has meaning or is accident</li><li>Whether consciousness is mechanistic or transcendent</li><li>Whether beauty matters or is illusion</li></ul><p><strong>These belong to you.</strong> Science gives you precision. Philosophy and art give you meaning. Both are true.</p><hr><h2 id="the-research-loop" tabindex="-1">The Research Loop <a class="header-anchor" href="#the-research-loop" aria-label="Permalink to “The Research Loop”">​</a></h2><p>The <strong>diamond-complete research loop:</strong></p><ol><li><strong>Spin online</strong> — Read articles, books, papers. Collect facts.</li><li><strong>Audit offline</strong> — Fact-check against sealed theorems. Mark contradictions.</li><li><strong>Lean-green in all dimensions</strong> — Translate to decidable arithmetic. Seal new theorems.</li></ol><p>This folder is the <strong>spin</strong> phase: the sealed proofs and honest questions that ground inquiry.</p>`,49)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};